//! End-to-end contract test for the gimli DWARF line number program reader.
//!
//! The same generated bytes are consumed two ways:
//!
//! 1. `IncompleteLineProgram::rows()` over a cloned program (full execution);
//! 2. `sequences()`, followed by `resume_from()` in reverse sequence order and
//!    a repeated resume of the first sequence (proving resumed runs do not
//!    leak state into one another).
//!
//! Every produced row is compared against an independent reference model that
//! advances VLIW operation slots one at a time. A handful of corrupted inputs
//! is additionally required to fail with explicit errors instead of panicking
//! or borrowing bytes from a neighbouring unit.

#[path = "support/leb.rs"]
mod leb;
#[path = "support/model.rs"]
mod model;
#[path = "support/generator.rs"]
mod generator;

use std::panic::{catch_unwind, AssertUnwindSafe};

use gimli::{
    AttributeValue, ColumnType, DebugLine, DebugLineOffset, EndianSlice, Endianity, Error,
    LineRow,
};

use generator::{all_combos, build, corrupt_units, Combo, CorruptKind, Endian};
use model::{LineModel, ModelInstr, ModelParams, ModelRow, ModelSequence};

/// Owned snapshot of one produced row, so rows from different read modes can
/// be compared away from the reader's borrows.
#[derive(Clone, Debug, PartialEq, Eq)]
struct RowSnap {
    address: u64,
    op_index: u64,
    file: u64,
    file_name: Vec<u8>,
    line: Option<u64>,
    column: ColumnType,
    is_stmt: bool,
    isa: u64,
    discriminator: u64,
    basic_block: bool,
    prologue_end: bool,
    epilogue_begin: bool,
    end_sequence: bool,
}

fn snapshot<E: Endianity>(row: &LineRow, header: &gimli::LineProgramHeader<EndianSlice<'_, E>>) -> RowSnap {
    let file_name = match row.file(header) {
        Some(entry) => match entry.path_name() {
            AttributeValue::String(r) => r.slice().to_vec(),
            other => panic!("LINE_MODEL_MISMATCH field=file_name unexpected attribute {other:?}"),
        },
        None => panic!(
            "LINE_MODEL_MISMATCH field=file actual=<unresolved file index {}>",
            row.file_index()
        ),
    };
    RowSnap {
        address: row.address(),
        op_index: row.op_index(),
        file: row.file_index(),
        file_name,
        line: row.line().map(|n| n.get()),
        column: row.column(),
        is_stmt: row.is_stmt(),
        isa: row.isa(),
        discriminator: row.discriminator(),
        basic_block: row.basic_block(),
        prologue_end: row.prologue_end(),
        epilogue_begin: row.epilogue_begin(),
        end_sequence: row.end_sequence(),
    }
}

fn mismatch(
    combo: &Combo,
    sequence: usize,
    row: usize,
    field: &str,
    actual: &dyn std::fmt::Debug,
    expected: &dyn std::fmt::Debug,
) -> ! {
    panic!(
        "LINE_MODEL_MISMATCH combo={} sequence={} row={} field={} actual={actual:?} expected={expected:?}",
        combo.label(),
        sequence,
        row,
        field,
    );
}

fn check_row(combo: &Combo, seq_idx: usize, row_idx: usize, snap: &RowSnap, expected: &ModelRow, expected_name: &[u8]) {
    macro_rules! cmp {
        ($field:ident, $value:expr) => {
            if snap.$field != $value {
                mismatch(combo, seq_idx, row_idx, stringify!($field), &snap.$field, &$value);
            }
        };
    }
    cmp!(address, expected.address);
    cmp!(op_index, expected.op_index);
    cmp!(file, expected.file);
    if snap.file_name != expected_name {
        mismatch(
            combo,
            seq_idx,
            row_idx,
            "file_name",
            &String::from_utf8_lossy(&snap.file_name),
            &String::from_utf8_lossy(expected_name),
        );
    }
    let expected_line = if expected.line == 0 { None } else { Some(expected.line) };
    cmp!(line, expected_line);
    let expected_column = match expected.column {
        0 => ColumnType::LeftEdge,
        n => ColumnType::Column(n.try_into().expect("non-zero column")),
    };
    cmp!(column, expected_column);
    cmp!(is_stmt, expected.is_stmt);
    cmp!(isa, expected.isa);
    cmp!(discriminator, expected.discriminator);
    cmp!(basic_block, expected.basic_block);
    cmp!(prologue_end, expected.prologue_end);
    cmp!(epilogue_begin, expected.epilogue_begin);
    cmp!(end_sequence, expected.end_sequence);
}

fn check_sequence(
    combo: &Combo,
    seq_idx: usize,
    snaps: &[RowSnap],
    expected: &ModelSequence,
    model: &LineModel,
) {
    if snaps.len() != expected.rows.len() {
        mismatch(
            combo,
            seq_idx,
            usize::MAX,
            "row_count",
            &snaps.len(),
            &expected.rows.len(),
        );
    }
    for (row_idx, (snap, want)) in snaps.iter().zip(expected.rows.iter()).enumerate() {
        let want_name = model.file_name(want.file);
        check_row(combo, seq_idx, row_idx, snap, want, &want_name);
    }
    let first = &snaps[0];
    let last = snaps.last().unwrap();
    if first.address != expected.start {
        mismatch(combo, seq_idx, 0, "sequence_start", &first.address, &expected.start);
    }
    if last.address != expected.end || !last.end_sequence {
        mismatch(
            combo,
            seq_idx,
            snaps.len() - 1,
            "sequence_end",
            &(last.address, last.end_sequence),
            &(expected.end, true),
        );
    }
}

fn build_model(combo: &Combo, instrs: &[ModelInstr], initial_files: &[Vec<u8>]) -> LineModel {
    let params = ModelParams {
        version: combo.version,
        minimum_instruction_length: u64::from(combo.min_insn_len),
        maximum_operations_per_instruction: u64::from(combo.max_ops),
        default_is_stmt: true,
        line_base: -3,
        line_range: 10,
        opcode_base: 13,
    };
    let mut model = LineModel::new(params, b"main.rs", initial_files);
    model.run(instrs);
    model
}

fn run_combo<E: Endianity>(combo: &Combo, endian: E) {
    let (bytes, comp_name, initial_files, instrs) = build(combo);
    let model = build_model(combo, &instrs, &initial_files);

    // Structural preconditions: the generator must actually exercise VLIW
    // slots, carries, and twenty-plus rows per sequence.
    assert_eq!(model.sequences.len(), 2, "two sequences were planned");
    for (idx, sequence) in model.sequences.iter().enumerate() {
        let ordinary = sequence.rows.iter().filter(|r| !r.end_sequence).count();
        assert!(ordinary >= 20, "sequence {idx} needs >= 20 ordinary rows, got {ordinary}");
    }
    if combo.max_ops > 1 {
        let nonzero_slots = model
            .sequences
            .iter()
            .flat_map(|s| s.rows.iter())
            .filter(|r| r.op_index != 0 && !r.end_sequence)
            .count();
        assert!(nonzero_slots > 0, "combo {} never uses a non-zero slot", combo.label());
        let same_address_slots = model.sequences.iter().any(|s| {
            s.rows.windows(2).any(|w| {
                w[0].address == w[1].address
                    && w[0].op_index != w[1].op_index
                    && !w[0].end_sequence
            })
        });
        assert!(
            same_address_slots,
            "combo {} lacks consecutive rows sharing an address across slots",
            combo.label()
        );
    }

    let debug_line = DebugLine::new(&bytes, endian);
    let comp = comp_name
        .as_ref()
        .map(|name| EndianSlice::new(name.as_slice(), endian));
    let program = debug_line
        .program(DebugLineOffset(0), 4, None, comp)
        .unwrap_or_else(|e| panic!("LINE_MODEL_MISMATCH combo={} field=parse actual={e:?}", combo.label()));

    // ---- Read mode A: full execution via cloned program.rows() ----------
    let mut all_rows: Vec<RowSnap> = Vec::new();
    {
        let mut rows = program.clone().rows();
        loop {
            match rows.next_row() {
                Ok(Some((header, row))) => all_rows.push(snapshot(row, header)),
                Ok(None) => break,
                Err(e) => panic!("LINE_MODEL_MISMATCH combo={} field=rows actual={e:?}", combo.label()),
            }
        }
    }
    let expected_total: usize = model.sequences.iter().map(|s| s.rows.len()).sum();
    if all_rows.len() != expected_total {
        mismatch(combo, usize::MAX, usize::MAX, "total_row_count", &all_rows.len(), &expected_total);
    }
    let mut offset = 0;
    for (seq_idx, sequence) in model.sequences.iter().enumerate() {
        let slice = &all_rows[offset..offset + sequence.rows.len()];
        check_sequence(combo, seq_idx, slice, sequence, &model);
        offset += sequence.rows.len();
    }

    // ---- Read mode B: sequences(), reverse resume_from, repeated resume --
    let (complete, sequences) = program
        .clone()
        .sequences()
        .unwrap_or_else(|e| panic!("LINE_MODEL_MISMATCH combo={} field=sequences actual={e:?}", combo.label()));
    if sequences.len() != model.sequences.len() {
        mismatch(combo, usize::MAX, usize::MAX, "sequence_count", &sequences.len(), &model.sequences.len());
    }
    for (idx, sequence) in sequences.iter().enumerate() {
        if sequence.start != model.sequences[idx].start {
            mismatch(combo, idx, 0, "sequence_start", &sequence.start, &model.sequences[idx].start);
        }
        if sequence.end != model.sequences[idx].end {
            mismatch(combo, idx, usize::MAX, "sequence_end", &sequence.end, &model.sequences[idx].end);
        }
    }

    let mut reversed: Vec<Vec<RowSnap>> = Vec::new();
    for seq_idx in (0..sequences.len()).rev() {
        let mut snaps = Vec::new();
        let mut rows = complete.resume_from(&sequences[seq_idx]);
        loop {
            match rows.next_row() {
                Ok(Some((header, row))) => snaps.push(snapshot(row, header)),
                Ok(None) => break,
                Err(e) => panic!(
                    "LINE_MODEL_MISMATCH combo={} sequence={seq_idx} field=resume actual={e:?}",
                    combo.label()
                ),
            }
        }
        check_sequence(combo, seq_idx, &snaps, &model.sequences[seq_idx], &model);
        reversed.push(snaps);
    }

    // Repeatedly resume the first sequence: the second run must be identical,
    // proving resume_from does not carry state over from prior runs.
    let mut repeat: Vec<RowSnap> = Vec::new();
    {
        let mut rows = complete.resume_from(&sequences[0]);
        loop {
            match rows.next_row() {
                Ok(Some((header, row))) => repeat.push(snapshot(row, header)),
                Ok(None) => break,
                Err(e) => panic!(
                    "LINE_MODEL_MISMATCH combo={} sequence=0 field=repeat_resume actual={e:?}",
                    combo.label()
                ),
            }
        }
    }
    let first_run = reversed.last().expect("reverse run covered the first sequence");
    if repeat != *first_run {
        mismatch(combo, 0, usize::MAX, "repeat_resume_state", &repeat, first_run);
    }
}

#[test]
fn line_contract() {
    let combos = all_combos();
    for combo in &combos {
        match combo.endian {
            Endian::Little => run_combo(combo, gimli::LittleEndian),
            Endian::Big => run_combo(combo, gimli::BigEndian),
        }
    }
    assert_eq!(combos.len(), 24);
    println!("LINE_CONTRACT_CASES=24");

    run_corruption_guards();
}

/// Corrupted programs must produce explicit errors, must not panic, and must
/// not consume bytes belonging to the unit placed immediately afterwards.
fn run_corruption_guards() {
    for case in corrupt_units() {
        let outcome = catch_unwind(AssertUnwindSafe(|| {
            let debug_line = DebugLine::new(&case.corrupt, gimli::LittleEndian);
            let program = debug_line.program(DebugLineOffset(0), 4, None, None)?;
            // The header parsed (truncation is inside the program): executing
            // it has to fail while still bounded by this unit's length.
            let mut rows = program.clone().rows();
            while let Some(..) = rows.next_row()? {}
            let (_, sequences) = program.sequences()?;
            Ok::<usize, Error>(sequences.len())
        }));

        let result: Result<usize, Error> = outcome.unwrap_or_else(|panic| {
            panic!("LINE_MODEL_MISMATCH corruption={} panicked: {panic:?}", case.name)
        });
        let err = match result {
            Err(e) => e,
            Ok(ok) => panic!(
                "LINE_MODEL_MISMATCH corruption={} accepted bad input, got {ok:?}",
                case.name
            ),
        };
        match case.expected {
            CorruptKind::HeaderZero => assert!(
                matches!(
                    err,
                    Error::MaximumOperationsPerInstructionZero | Error::LineRangeZero
                ),
                "corruption {}: unexpected error {err:?}",
                case.name
            ),
            CorruptKind::Truncated => assert!(
                matches!(err, Error::UnexpectedEof(..) | Error::BadUnsignedLeb128),
                "corruption {}: unexpected error {err:?}",
                case.name
            ),
        }

        // The neighbouring, well-formed unit must still parse in full.
        let neighbour_offset = case.corrupt.len();
        let debug_line = DebugLine::new(&case.section, gimli::LittleEndian);
        let program = debug_line
            .program(DebugLineOffset(neighbour_offset), 4, None, None)
            .expect("neighbour unit must remain independently parseable");
        let (_, sequences) = program
            .sequences()
            .expect("neighbour unit must execute in full");
        assert_eq!(sequences.len(), 1, "neighbour unit boundary was disturbed");
    }
}
